package com.example.rokidgeminisecretary;
import android.content.*;import android.view.*;import android.widget.*;import android.os.*;import java.util.concurrent.*;import java.util.concurrent.atomic.*;
public final class PhoneWorkspaceChecks {
 static int n;static void ok(boolean value){n++;if(!value)throw new AssertionError("phone workspace "+n);}
 public static int run(Context base)throws Exception{n=0;AtomicReference<Throwable> failure=new AtomicReference<>();CountDownLatch done=new CountDownLatch(1);new Handler(Looper.getMainLooper()).post(()->{try{Context c=new android.view.ContextThemeWrapper(base,android.R.style.Theme_Material_Light);LinearLayout root=PhoneWorkspaceLayout.panel(c);EditText draft=new EditText(c);draft.setText("未送信の質問・写真について");draft.setSelection(3,7);LinearLayout conversation=PhoneWorkspaceLayout.panel(c);conversation.addView(draft);AtomicInteger actions=new AtomicInteger();Button send=new Button(c);send.setOnClickListener(v->actions.incrementAndGet());conversation.addView(send);LinearLayout navBody=PhoneWorkspaceLayout.panel(c);EditText destination=new EditText(c);destination.setText("合成の目的地");navBody.addView(destination);TextView longBody=new TextView(c);longBody.setText("保存したルート");navBody.addView(longBody,new LinearLayout.LayoutParams(-1,6000));ScrollView nav=PhoneWorkspaceLayout.scroll(c,navBody);View[] pages={conversation,nav,PhoneWorkspaceLayout.panel(c),PhoneWorkspaceLayout.panel(c)};PhoneWorkspaceLayout layout=new PhoneWorkspaceLayout(c,root,pages,null);ok(layout.current()==0);ViewParent inputParent=draft.getParent();for(int i=0;i<100;i++){layout.show(i%4);ok(draft.getText().toString().equals("未送信の質問・写真について"));ok(draft.getSelectionStart()==3&&draft.getSelectionEnd()==7);ok(draft.getParent()==inputParent);ok(destination.getText().toString().equals("合成の目的地"));ok(actions.get()==0);int shown=0;for(View page:pages)if(page.getVisibility()==View.VISIBLE)shown++;ok(shown==1);}layout.show(1);root.measure(View.MeasureSpec.makeMeasureSpec(1080,View.MeasureSpec.EXACTLY),View.MeasureSpec.makeMeasureSpec(1920,View.MeasureSpec.EXACTLY));root.layout(0,0,1080,1920);nav.scrollTo(0,400);ok(nav.getScrollY()==400);layout.show(3);layout.show(1);ok(nav.getScrollY()==400);layout.show(0);send.performClick();ok(actions.get()==1);boolean bad=false;try{layout.show(4);}catch(IllegalArgumentException expected){bad=true;}ok(bad);ok(layout.current()==0);LinearLayout moved=PhoneWorkspaceLayout.panel(c);PhoneWorkspaceLayout.add(moved,destination);ok(navBody.indexOfChild(destination)==-1);ok(destination.getParent()==moved);ok(destination.getText().toString().equals("合成の目的地"));}catch(Throwable t){failure.set(t);}finally{done.countDown();}});if(!done.await(30,TimeUnit.SECONDS))throw new AssertionError("Phone UI thread timeout");if(failure.get()!=null)throw new AssertionError("Phone workspace failed",failure.get());return n;}
}
